<script>(()=>{const body=document.querySelector('#bags'),tpl=document.querySelector('#bagTemplate'),ordered=document.querySelector('#orderedKg'),orderedOut=document.querySelector('#totalOrdered'),receivedOut=document.querySelector('#totalReceived'),varianceOut=document.querySelector('#totalVariance');let i=0;function totals(){const o=parseFloat(ordered.value)||0;let received=0;body.querySelectorAll('[data-farm]').forEach(x=>received+=parseFloat(x.value)||0);const variance=received-o;orderedOut.textContent=o.toFixed(2)+' kg';receivedOut.textContent=received.toFixed(2)+' kg';varianceOut.textContent=(variance>0?'+':'')+variance.toFixed(2)+' kg';varianceOut.className=variance<0?'feed-negative':'feed-positive'}function add(){const row=tpl.content.firstElementChild.cloneNode(true),n=i++,feed=row.querySelector('[data-feed]'),store=row.querySelector('[data-store]'),farm=row.querySelector('[data-farm]'),variance=row.querySelector('[data-var]');feed.name=`bags[${n}][feed_name]`;store.name=`bags[${n}][supplier_weight_kg]`;farm.name=`bags[${n}][farm_weight_kg]`;row.querySelector('[data-row]').textContent=n+1;const calc=()=>{const v=(parseFloat(farm.value)||0)-(parseFloat(store.value)||0);variance.textContent=(v>0?'+':'')+v.toFixed(2)+' kg';variance.className=v<0?'feed-negative':'feed-positive';totals()};store.oninput=farm.oninput=calc;row.querySelector('[data-remove]').onclick=()=>{row.remove();totals()};body.appendChild(row)}document.querySelector('#addBag').onclick=add;ordered.oninput=totals;add();totals()})();</script>@endif
